 static void decorate(GameTestHelper h,ServerPlayer p,ServerPlayer admin)throws Exception{var from=BASE.offset(16,0,0);var to=from.offset(15,0,5);for(var pos:BlockPos.betweenClosed(from,to)){h.assertTrue(p.serverLevel().getBlockState(pos).isAir(),"Decorative plot never replaces existing work");p.serverLevel().setBlock(pos.below(),Blocks.STONE.defaultBlockState(),3);}var nonce=RetainedBuildingService.reviewSite(admin,p,"kingdom_smp:builder/m02",from,to,"Authorized varied decorative civic masonry with supplied stairs slabs walls and owner consent");RetainedBuildingService.confirmSite(admin,nonce);for(int x=0;x<16;x++)for(int z=0;z<6;z++)place(h,p,from.offset(x,0,z),z<2?Items.STONE_BRICK_STAIRS:z<4?Items.STONE_BRICK_SLAB:Items.COBBLESTONE_WALL);}
 static void place(GameTestHelper h,ServerPlayer p,BlockPos pos,Item item){var level=p.serverLevel();Direction face=null;BlockPos clicked=null;for(var direction:Direction.values()){var neighbor=pos.relative(direction);if(!level.getBlockState(neighbor).getCollisionShape(level,neighbor).isEmpty()){clicked=neighbor;face=direction.getOpposite();break;}}if(clicked==null)throw new IllegalStateException("No real native supporting neighbor: "+pos);var held=p.getMainHandItem().copy();p.moveTo(pos.getX()+2.5,pos.getY()+2,pos.getZ()+2.5);p.setYRot(0);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(item));p.gameMode.useItemOn(p,level,p.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(clicked).add(Vec3.atLowerCornerOf(face.getNormal()).scale(.5)),face,clicked,false));h.assertTrue(WorkstationCompatibility.canonicalState(level.getBlockState(pos),Block.byItem(item).defaultBlockState()).getBlock().asItem()==item&&p.getMainHandItem().isEmpty(),"Actual native supplied placement and item debit at "+pos);p.setItemInHand(InteractionHand.MAIN_HAND,held);}
